<?php

  // recurrencepicker - Native fieldset emits `{kind,start,timezone,interval,count,byday,exclude}`. Daily/weekly/monthly/yearly subset; interval/count 1..100. Weekly byday accepts comma-separated MO..SU; other frequencies reject it. Explicit exclusions are newline/comma-separated dates/instants. `padInputRecurrence($posted)` validates through padOccurrences and returns kind/rule plus preview for one year. Call it server-side before saving. Submitted invalid values are retained, with an error and correction controls. Submit updates authoritative preview; reset uses native form behavior. This deliberately has no independent browser recurrence implementation.
  //
  // ## Example
  //
  // ```pad
  // {input:form 'recurrencepicker'}{input:recurrencepicker 'schedule', label='Schedule'/}<button type='submit'>Preview</button><button type='reset'>Reset</button>{/input:form}
  // ```
  //
  // Run the focused fixture with `php tests/subsystems/input-recurrencepicker.php`.

include_once PAD.'subs/inputs/_lib/recurrencepicker.php';
$given=padInputTake('value',['kind'=>'daily','start'=>'2026-11-02','timezone'=>'UTC','interval'=>1,'count'=>10]);$name=padInputName();$source=padFormSource();if($source!==NULL){[$found,$posted]=padFormFind($source,$name);if($found)$given=$posted;}$invalid='';$preview=[];try{$preview=padInputRecurrence($given)['occurrences'];}catch(Exception $e){$invalid=$e->getMessage();}if(!is_array($given))$given=[];
return padInputField(function($head,$rest,$label,$error,$id,$worded)use($given,$invalid,$preview,$name){$disabled=isset($GLOBALS['padInputNow']['attrs']['disabled']);$h='<fieldset id="'.padInputEscape($id).'"'.($disabled?' disabled':'').'><legend>'.padInputEscape($worded).'</legend>';foreach(['kind'=>'Frequency','start'=>'Start date or local date/time','timezone'=>'Timezone','interval'=>'Every','count'=>'Occurrences','byday'=>'Weekly days (MO,TU,...)','exclude'=>'Excluded dates or instants, one per line'] as $key=>$title){$cid=$id.'-'.$key;$v=is_scalar($given[$key]??NULL)?(string)$given[$key]:'';$h.='<div><label for="'.padInputEscape($cid).'">'.$title.'</label>';$attrs=' id="'.padInputEscape($cid).'" name="'.padInputEscape($name.'['.$key.']').'"';if($key==='kind'){$h.='<select'.$attrs.'>';foreach(['daily','weekly','monthly','yearly'] as $kind)$h.='<option'.($v===$kind?' selected':'').' value="'.$kind.'">'.ucfirst($kind).'</option>';if($v!==''&&!in_array($v,['daily','weekly','monthly','yearly'],TRUE))$h.='<option selected value="'.padInputEscape($v).'">'.padInputEscape($v).' (unsupported)</option>';$h.='</select>';}elseif($key==='exclude')$h.='<textarea'.$attrs.'>'.padInputEscape($v).'</textarea>';else $h.='<input'.$attrs.' type="'.(in_array($key,['interval','count'],TRUE)?'number':'text').'"'.(in_array($key,['interval','count'],TRUE)?' min="1" max="100" step="1"':'').' value="'.padInputEscape($v).'">';$h.='</div>';}$h.='<p>Submit the form to validate and preview the next year.</p>';if($invalid!=='')$h.='<p role="alert">'.padInputEscape($invalid).'</p>';else{$h.='<details open><summary>Occurrence preview (next year)</summary><ol>';foreach($preview as $date)$h.='<li>'.padInputEscape($date).'</li>';$h.='</ol></details>';}return padInputFrame('recurrencepicker',$worded,$h.'</fieldset>',$error);});
